const lifeExerciseSearchScore = (ex, query) => {
    const q = lifeNormalizeText(query).trim();
    if (!q)
        return 0;
    const name = lifeNormalizeText(ex?.name), hay = lifeNormalizeText(`${ex?.name || ''} ${ex?.muscle_group || ''} ${ex?.equipment || ''}`), words = name.split(/[^a-z0-9]+/).filter(Boolean), tokens = q.split(/[^a-z0-9]+/).filter(Boolean), expanded = tokens.map(t => LIFE_EXERCISE_SEARCH_ALIASES[t] || t);
    let score = 0;
    const popularIndex = LIFE_EXERCISE_POPULAR.findIndex(x => lifeNormalizeText(x) === name);
    if (popularIndex >= 0)
        score += 180 - (popularIndex * 8);
    expanded.forEach(t => { if (words.some(w => w === t))
        score += 220;
    else if (words.some(w => w.startsWith(t)))
        score += 170;
    else if (hay.includes(t))
        score += 80; });
    if (name === q)
        score += 1000;
    if (name.startsWith(q))
        score += 700;
    if (hay.includes(q))
        score += 360;
    tokens.forEach((t, idx) => {
        if (words.some(w => w === t))
            score += 180 - (idx * 4);
        else if (words.some(w => w.startsWith(t)))
            score += 130 - (idx * 4);
        else if (hay.includes(t))
            score += 60 - (idx * 3);
        else
            score -= 220;
    });
    if (tokens.length && tokens.every(t => words.some(w => w.startsWith(t)) || hay.includes(t)))
        score += 220;
    return score;
};
const lifeSearchExercises = (query, group = 'Todos', limit = 12) => {
    const q = lifeNormalizeText(query).trim();
    let pool = IRON_EXERCISE_LIBRARY.filter(ex => lifeExerciseBelongsToGroup(ex, group));
    if (!q) {
        const picks = LIFE_EXERCISE_POPULAR.map(name => pool.find(ex => lifeNormalizeText(ex.name) === lifeNormalizeText(name))).filter(Boolean);
        return [...picks, ...pool.filter(ex => !picks.some(p => p.id === ex.id))].slice(0, limit);
    }
    return pool.map(ex => ({ ex, score: lifeExerciseSearchScore(ex, q) })).filter(x => x.score > 0).sort((a, b) => b.score - a.score || a.ex.name.localeCompare(b.ex.name, 'pt-BR')).slice(0, limit).map(x => x.ex);
};
