const lifeFindExercise = (name, group) => {
    const wanted = lifeNormalizeText(name);
    return IRON_EXERCISE_LIBRARY.find(ex => lifeNormalizeText(ex.name) === wanted) || IRON_EXERCISE_LIBRARY.find(ex => lifeExerciseBelongsToGroup(ex, group) && lifeNormalizeText(ex.name).includes(wanted.split(' ')[0]));
};
const lifeBuildMuscleWorkout = (raw, age = 18) => {
    const targets = lifeExtractMuscleTargets(raw);
    if (!targets.length)
        return null;
    const multi = targets.length > 1, chosen = [];
    targets.slice(0, 3).forEach(group => {
        const wanted = (LIFE_WORKOUT_PRIORITY[group] || []).slice(0, multi ? 3 : (group === 'Pernas' ? 6 : 5));
        wanted.forEach(name => { const ex = lifeFindExercise(name, group); if (ex && !chosen.some(x => x.ex.id === ex.id))
            chosen.push({ ex, group }); });
        if (chosen.filter(x => x.group === group).length < (multi ? 3 : 4)) {
            IRON_EXERCISE_LIBRARY.filter(ex => lifeExerciseBelongsToGroup(ex, group)).slice(0, 6).forEach(ex => { if (!chosen.some(x => x.ex.id === ex.id) && chosen.filter(x => x.group === group).length < (multi ? 3 : 4))
                chosen.push({ ex, group }); });
        }
    });
    const safeAge = Number(age) || 18;
    const prescription = chosen.map(({ ex, group }, i) => { const isolation = /rosca|tr[ií]ceps|lateral|extensora|flexora|panturr|punho|encolhimento|abdominal/i.test(ex.name); const reps = group === 'Panturrilha' ? '12–20' : group === 'Abdômen' ? '10–15 ou 30–45s' : isolation ? '10–15' : '8–12'; return { sets: 3, reps, rest: isolation ? 60 : 90 }; });
    const moves = chosen.map(x => x.ex.name);
    const title = 'Treino de ' + targets.join(' + ');
    const lines = chosen.map((x, i) => `${i + 1}. ${x.ex.name} — ${prescription[i].sets}×${prescription[i].reps}`).join('\n');
    const ageNote = safeAge < 18 ? ' Mantive um volume moderado e sem séries máximas; técnica e supervisão adequada vêm primeiro.' : '';
    return { targets, text: `${title}\n\n${lines}\n\nDescanso: cerca de 60–90s entre séries.${ageNote} Se quiser, abra o treino e toque em cada exercício na biblioteca para ver execução, vídeo e erros comuns.`, data: { id: 'ai_muscle_' + targets.map(x => lifeNormalizeText(x)).join('_'), name: title, type: 'Hipertrofia', level: 'Intermediário', days: 1, moves, items: moves, prescription, exerciseRefs: chosen.map(x => x.ex.id) } };
};
const lifeIsSimpleGreeting = (text) => /^(oi+|ol[aá]+|opa+|e\s*a[ií]+|eae+|fala+|salve+|bom\s+dia|boa\s+tarde|boa\s+noite)[!,.? ]*$/i.test(String(text || '').trim());
const IRON_GOALS = ['Hipertrofia', 'Força', 'Condicionamento', 'Resistência muscular', 'Saúde e performance'];
const IRON_LEVELS = ['Iniciante', 'Intermediário', 'Avançado', 'Retorno gradual', 'Experiência mista'];
const IRON_SPLITS = {
    2: ['Full Body A/B'],
    3: ['Full Body', 'Push / Pull / Legs'],
    4: ['Upper / Lower', 'Upper / Lower + Full Body'],
    5: ['Push / Pull / Legs + Upper / Lower', 'Upper / Lower + braços e core'],
    6: ['Push / Pull / Legs ×2']
};
const IRON_DAY_SETS = {
    2: [[1, 4]], 3: [[1, 3, 5]], 4: [[1, 2, 4, 5]], 5: [[1, 2, 3, 5, 6]], 6: [[1, 2, 3, 4, 5, 6]]
};
const IRON_DAY_NAMES = ['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];
function buildWeeklyPlan(days, goal, level, splitName, hybrid = false) {
    const selectedDays = IRON_DAY_SETS[days]?.[0] || [1, 3, 5];
    const groups = hybrid
        ? ['Corrida + força', 'Musculação + corrida', 'Corrida leve + core', 'Descanso/recuperação', 'Corrida + força', 'Mobilidade', 'Descanso']
        : ['Peito + tríceps', 'Costas + bíceps', 'Pernas', 'Ombros + core', 'Full Body', 'Braços + core', 'Descanso'];
    return IRON_DAY_NAMES.map((dayName, i) => {
        const dayNumber = i + 1;
        const active = selectedDays.includes(dayNumber);
        const group = active ? groups[i] : 'Descanso / recuperação';
        const pool = hybrid
            ? IRON_EXERCISE_LIBRARY.filter(e => ['Pernas', 'Core', 'Peito', 'Costas'].includes(e.muscle_group))
            : IRON_EXERCISE_LIBRARY.filter(e => {
                if (group.includes('Peito'))
                    return ['Peito', 'Tríceps'].includes(e.muscle_group);
                if (group.includes('Costas'))
                    return ['Costas', 'Bíceps'].includes(e.muscle_group);
                if (group === 'Pernas')
                    return ['Pernas', 'Glúteos', 'Panturrilhas'].includes(e.muscle_group);
                if (group.includes('Ombros'))
                    return ['Ombros', 'Core'].includes(e.muscle_group);
                if (group.includes('Braços'))
                    return ['Bíceps', 'Tríceps', 'Core'].includes(e.muscle_group);
                return true;
            });
        const exercises = active ? (pool.length ? pool : IRON_EXERCISE_LIBRARY).slice(0, hybrid ? 5 : 6).map(e => ({
            name: e.name, exercise_id: e.id, sets: level === 'Avançado' ? 4 : 3, reps: goal === 'Força' ? '4–6' : '8–12', video_id: e.video_id, video_url: e.video_url
        })) : [];
        return { day: dayNumber, dayName, active, focus: group, exercises };
    });
}
const PREBUILT_WORKOUTS_EXPANDED = (() => {
    const list = [];
    ['Mulheres', 'Homens'].forEach(target => {
        let n = 0;
        IRON_GOALS.forEach(goal => IRON_LEVELS.forEach(level => [2, 3, 4, 5, 6].forEach(days => {
            n++;
            const split = IRON_SPLITS[days][n % IRON_SPLITS[days].length];
            list.push({
                id: `pre_${target === 'Mulheres' ? 'f' : 'm'}_${n}`,
                target, category: goal, level, days: IRON_DAY_SETS[days][0],
                frequency: days, split, desc: `Plano ${goal.toLowerCase()} • ${level.toLowerCase()} • ${days} dias/semana.`,
                weeklyPlan: buildWeeklyPlan(days, goal, level, split, false)
            });
        })));
    });
    return list;
})();
const HYBRID_WORKOUTS = (() => {
    const list = [];
    let n = 0;
    IRON_GOALS.forEach(goal => IRON_LEVELS.forEach(level => [3, 4].forEach(days => {
        n++;
        list.push({
            id: `hybrid_${n}`, target: 'Híbrido', category: goal, level, frequency: days,
            days: IRON_DAY_SETS[days][0], split: 'Corrida + musculação',
            desc: `Alternância planejada entre corrida e musculação • ${days} dias/semana.`,
            weeklyPlan: buildWeeklyPlan(days, goal, level, 'Corrida + musculação', true)
        });
    })));
    return list;
})();
