function lifeParseDateV4(value) { const d = value ? new Date(value) : null; return d && !Number.isNaN(d.getTime()) ? d : null; }
function lifeStartOfTodayV4() { const d = new Date(); d.setHours(0, 0, 0, 0); return d; }
function lifeTaskStatusV4(task) {
    const due = lifeParseDateV4(task?.dueAt), today = lifeStartOfTodayV4(), end7 = new Date(today.getTime() + 7 * 86400000);
    if (task?.waiting)
        return 'Aguardando';
    if (!due)
        return 'Sem data';
    if (due < today && !task?.done && !task?.completed)
        return 'Atrasada';
    if (due >= today && due < new Date(today.getTime() + 86400000))
        return 'Hoje';
    if (due <= end7)
        return '7 dias';
    return 'Depois';
}
function lifeTaskScoreV4(task) {
    let score = 0;
    const st = lifeTaskStatusV4(task), p = String(task?.priority || 'Normal');
    if (st === 'Atrasada')
        score += 90;
    if (st === 'Hoje')
        score += 70;
    if (st === '7 dias')
        score += 40;
    if (st === 'Sem data')
        score += 5;
    if (p === 'Alta')
        score += 35;
    if (p === 'Média')
        score += 18;
    const dur = Number(task?.duration || 30);
    if (dur <= 15)
        score += 8;
    if (task?.waiting)
        score -= 100;
    return score;
}
function lifeScaleIngredientV4(text, scale) {
    const raw = String(text || '');
    if (scale === 1)
        return raw;
    const fractionMap = { '½': 0.5, '¼': 0.25, '¾': 0.75, '⅓': 1 / 3, '⅔': 2 / 3, '⅛': 0.125 };
    const trimmed = raw.trim();
    let m = trimmed.match(/^(\d+)\s+(\d+)\/(\d+)(\s+.*)$/);
    if (m) {
        const val = (Number(m[1]) + Number(m[2]) / Number(m[3])) * scale;
        return (Number.isInteger(val) ? val : val.toFixed(2).replace('.', ',')) + m[4];
    }
    m = trimmed.match(/^(\d+)\/(\d+)(\s+.*)$/);
    if (m) {
        const val = (Number(m[1]) / Number(m[2])) * scale;
        return (Number.isInteger(val) ? val : val.toFixed(2).replace('.', ',')) + m[3];
    }
    const f = trimmed[0];
    if (fractionMap[f]) {
        const val = fractionMap[f] * scale;
        return (Number.isInteger(val) ? val : val.toFixed(2).replace('.', ',')) + trimmed.slice(1);
    }
    m = trimmed.match(/^(\d+(?:[\.,]\d+)?)(\s*.*)$/);
    if (m) {
        const val = Number(m[1].replace(',', '.')) * scale;
        return (Number.isInteger(val) ? val : val.toFixed(2).replace('.', ',')) + m[2];
    }
    return scale + '× ' + raw;
}
