        if (notificationPrefs.enabled === false || (prefKey && notificationPrefs[prefKey] === false))
            return;
        addLifeNotification('LIFE · ' + (reminder.category || 'Lembrete'), reminder.title, reminder.category || 'Lembrete', { reminderId: reminder.id });
