                return false;
            const { data: { session } } = await window.lifeSupabase.auth.getSession();
            if (!session?.user)
                return false;
            const map = { Tarefas: 'tasks', Estudos: 'studies', Fitness: 'fitness', Finanças: 'finance', Rotina: 'habits', Evento: 'events' };
            const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
            const payload = notificationPrefs.enabled === false ? [] : reminders.filter(r => r.enabled && (!map[r.category] || notificationPrefs[map[r.category]] !== false)).map(r => ({ id: r.id, title: r.title, category: r.category, when: r.when, repeat: r.repeat, enabled: r.enabled }));
            const { error } = await window.lifeSupabase.functions.invoke('life-notification-sync', { body: { reminders: payload, timezone, quiet_start: notificationPrefs.quietStart || '22:30', quiet_end: notificationPrefs.quietEnd || '07:00' } });
            if (error)
                throw error;
