    const enableLifePush = async () => {
        if (typeof Notification === 'undefined' || !('serviceWorker' in navigator)) {
            setPushStatus('unsupported');
            setToast('PUSH NÃO SUPORTADO NESTE NAVEGADOR');
            setTimeout(() => setToast(''), 2200);
            return;
        }
        try {
            const permission = await Notification.requestPermission();
            if (permission !== 'granted') {
                setPushStatus(permission === 'denied' ? 'blocked' : 'off');
                return;
            }
            const reg = await navigator.serviceWorker.register('./service-worker.js');
            let publicKey = window.LIFE_PUSH_PUBLIC_KEY || lifeRawStorageGet('life_push_public_key') || '';
            if (!publicKey && window.lifeSupabase) {
                try {
                    const { data } = await window.lifeSupabase.functions.invoke('life-push-config', { body: {} });
                    publicKey = data?.public_key || '';
                    if (publicKey)
                        lifeRawStorageSet('life_push_public_key', publicKey);
                }
                catch (e) { }
            }
            if (!publicKey) {
                setPushStatus('permission');
                setToast('PERMISSÃO ATIVA · FALTA CONFIGURAR O SERVIDOR PUSH');
                setTimeout(() => setToast(''), 3000);
                return;
            }
            let sub = await reg.pushManager.getSubscription();
            if (!sub)
                sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(publicKey) });
            if (window.lifeSupabase) {
                const { data: { session } } = await window.lifeSupabase.auth.getSession();
                if (session?.user) {
                    const { error } = await window.lifeSupabase.functions.invoke('life-push-register', { body: { subscription: sub.toJSON() } });
                    if (error)
                        throw error;
                }
            }
            setPushStatus('ready');
            await syncLifeNotificationQueue();
            setToast('NOTIFICAÇÕES FORA DO APP ATIVADAS');
            setTimeout(() => setToast(''), 2500);
        }
        catch (e) {
            console.warn('Push não ativado', e);
            setPushStatus('permission');
            setToast('PUSH PREPARADO · CONCLUA O BACKEND PARA USAR FORA DO APP');
            setTimeout(() => setToast(''), 3000);
        }
    };
