    const findLifeRecipes = () => {
        const parseMin = t => parseInt(String(t || '99')) || 99;
        const max = rfAnswers.time === 'Até 15 min' ? 15 : rfAnswers.time === 'Até 25 min' ? 25 : rfAnswers.time === 'Até 35 min' ? 35 : 999;
        const words = {
            'Frutas / aveia': ['fruta', 'aveia', 'banana', 'iogurte'],
            'Arroz / feijão': ['arroz', 'feijão', 'lentilha'],
            'Massa / legumes': ['massa', 'legumes'],
            'Batata / frango': ['batata', 'frango'],
            'Ovos / vegetais': ['ovos', 'vegetais']
        }[rfAnswers.base] || [];
        const ranked = v33Recipes.map(r => {
            let score = 0;
            if (parseMin(r.time) <= max)
                score += 5;
            if (rfAnswers.taste === 'Algo doce' && r.cat === 'Doce')
                score += 7;
            if (rfAnswers.taste === 'Algo salgado' && r.cat === 'Salgada')
                score += 7;
            if (rfAnswers.taste === 'Uma refeição' && ['Cozida', 'Grelhada', 'Assada', 'Salgada'].includes(r.cat))
                score += 5;
            if (rfAnswers.method === 'Forno' && r.method === 'forno')
                score += 6;
            if (rfAnswers.method === 'Panela' && r.method === 'panela')
                score += 6;
            if (rfAnswers.method === 'Frigideira' && r.method === 'frigideira')
                score += 6;
            if (rfAnswers.method === 'Poucos passos' && (r.cat === 'Rápida' || parseMin(r.time) <= 20))
                score += 5;
            const hay = (r.base + ' ' + r.name).toLowerCase();
            if (words.some(w => hay.includes(w)))
                score += 7;
            return { ...r, lifeMatch: score };
        }).sort((a, b) => b.lifeMatch - a.lifeMatch || a.id - b.id).slice(0, 8);
        setRfResults(ranked);
    };
